def rle_decode(s: str) -> str:
    result = []
    i = 0
    n = len(s)

    while i < n:
        c = s[i]

        if c == '#':
            raise ValueError("'#' must be preceded by a character")

        if i + 1 < n and s[i + 1] == '#':
            # Run token: character '#' digits
            j = i + 2
            if j >= n or not s[j].isdigit():
                raise ValueError("'#' must be followed by at least one digit")

            while j < n and s[j].isdigit():
                j += 1

            count = int(s[i + 2:j])
            if count < 4:
                raise ValueError("run length must be at least 4")

            result.append(c * count)
            i = j
        else:
            result.append(c)
            i += 1

    return ''.join(result)
